css:
.ed__rule { display: block; width: 3.5rem; height: 3px; border-radius: 3px; background: linear-gradient(90deg, var(--bff-leaf, #6b8e36), var(--bff-gold, #eec02b)); margin-bottom: clamp(1.4rem, 3vw, 2.2rem); }
.ed__grid { display: grid; gap: 1rem 3rem; padding-bottom: 2rem; }
@media (min-width: 62rem) { .ed__grid { grid-template-columns: minmax(0, 17rem) minmax(0, 1fr); } }
.ed__when { margin: 0 0 .6rem; }
.ed__day { margin: 0; font-family: var(--os-font-heading); font-weight: 380; font-size: clamp(1.7rem, 1.2rem + 1.6vw, 2.5rem); line-height: 1.05; color: var(--os-color-heading); }
.ed__meta { margin: .5rem 0 0; font-size: 1rem; line-height: 1.05; color: var(--bff-ink-2, #3f4f3b); }
.ed__next b { color: var(--os-color-link); font-weight: 700; }
.ed__title { margin: 0 0 .5em; font-size: clamp(2.1rem, 1.2rem + 3.4vw, 3.7rem); line-height: 1.08; letter-spacing: -.015em; }
.ed__deck { margin: 0 0 1.4rem; max-width: 34ch; font-family: var(--os-font-heading); font-weight: 380; font-size: clamp(1.3rem, 1.05rem + .8vw, 1.65rem); line-height: 1.3; text-wrap: balance; color: var(--os-color-heading); }
.ed__oh { margin: 0 0 .5em; font-size: 1.35rem; line-height: 1.15; letter-spacing: -.015em; }
.ed__offers { margin: 1em 0; padding-left: 1.2rem; list-style: disc; }
.ed__offers li { margin: 0; padding: .12rem 0; display: list-item; list-style: disc; max-width: 62ch; }
.ed__body { margin-top: 1.8rem; }
.ed__body p { margin: 1em 0 0; max-width: 62ch; }
.ed__body p + p { margin-top: 1.1em; }
.ed__body > :first-child, .ed__body .os-rich > :first-child { margin-top: 0; }
.ed__cta { margin: 1.4rem 0 1em; }
.ed__cta a { text-decoration: none; display: inline-block; }
.ed__btn { display: inline-flex; align-items: center; justify-content: center; padding: .6em 1.1em; border: 2px solid currentColor; border-radius: 999px; font: 700 .95rem/1.1 var(--os-font-body); color: var(--os-color-heading); transition: background-color .2s; }
.ed__btn:hover { background: var(--os-color-heading); color: var(--os-color-background); }
@media (max-width: 767px) { .ed__btn { min-height: 2.75rem; } }
@media (prefers-reduced-motion: reduce) { .ed__btn { transition: none; } }
